private fun symbol(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
    ).apply {
        addGroup(name = name, translationY = 960f)
        for (d in paths) {
            addPath(pathData = PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
        }
        clearGroup()
    }.build()

private fun brandSymbol(name: String, viewport: Float = 640f, vararg paths: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = viewport,
        viewportHeight = viewport,
    ).apply {
        for (d in paths) {
            addPath(pathData = PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
        }
    }.build()

fun Modifier.autoMirrored() = composed {
    val isRtl = LocalLayoutDirection.current == LayoutDirection.Rtl
    graphicsLayer { scaleX = if (isRtl) -1f else 1f }
}
